shell_commands:
cat << 'EOF' > patch_test.js
const fs = require('fs');
const file = 'src/orchestration/chatOrchestrator.test.ts';
let code = fs.readFileSync(file, 'utf8');

const oldCode = `  it('drives a stub provider through a rejected tool call followed by a corrected retry, and processMessage resolves', async () => {
    let capturedToolResult = '';
    const mockProvider: AIProvider = {
      async *sendMessage(params: SendMessageParams) {
        // Find the last message
        const lastMsg = params.messages[params.messages.length - 1];
        if (
          lastMsg &&
          lastMsg.role === 'user' &&
          typeof lastMsg.content === 'object' &&
          Array.isArray(lastMsg.content)
        ) {
          const toolResultBlock = lastMsg.content.find((c: any) => c.type === 'tool_result');
          if (toolResultBlock && toolResultBlock.type === 'tool_result' && toolResultBlock.content) {
            capturedToolResult = toolResultBlock.content;
          }
        }

        if (!capturedToolResult) {
          yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {wrong: 'yes'}}};
          yield {type: 'stop', stopReason: 'tool_use'};
        } else {
          yield {type: 'text', text: 'got the rejection'};
          yield {type: 'stop', stopReason: 'end_turn'};
        }
      },
    };

    const orchestrator = createChatOrchestrator(
      mockProvider,
      promptBuilder,
      registryReturning({result: 'Input validation failed: invalid'})
    );

    const result = await orchestrator.processMessage(createSession('ask'));
    expect(result).toBe('got the rejection');
    expect(capturedToolResult).toBe('Input validation failed: invalid');
  });`;

const newCode = `  it('drives a stub provider through a rejected tool call followed by a corrected retry, and processMessage resolves', async () => {
    let capturedToolResult = '';

    const isUserMsgWithContentArray = (msg: unknown): msg is {role: 'user'; content: unknown[]} =>
      msg !== undefined && msg !== null && typeof msg === 'object' && 'role' in msg && msg.role === 'user' && 'content' in msg && Array.isArray(msg.content);

    const mockProvider: AIProvider = {
      generateStructured: async () => ({}) as any,
      async *sendMessage(params: SendMessageParams) {
        const lastMsg = params.messages[params.messages.length - 1];

        if (isUserMsgWithContentArray(lastMsg)) {
          const block = lastMsg.content.find(
            (c: unknown): c is {type: 'tool_result'; content: string} => 
              typeof c === 'object' && c !== null && 'type' in c && (c as any).type === 'tool_result' && 'content' in c
          );
          capturedToolResult = block ? String(block.content) : capturedToolResult;
        }

        if (!capturedToolResult) {
          yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {wrong: 'yes'}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }

        if (capturedToolResult) {
          yield {type: 'text', text: 'got the rejection'};
          yield {type: 'stop', stopReason: 'end_turn'};
        }
      },
    };

    const orchestrator = createChatOrchestrator(
      mockProvider,
      promptBuilder,
      registryReturning({result: 'Input validation failed: invalid'})
    );

    const result = await orchestrator.processMessage(createSession('ask'));
    expect({result, capturedToolResult}).toEqual({
      result: 'got the rejection',
      capturedToolResult: 'Input validation failed: invalid',
    });
  });`;

if (code.includes(oldCode)) {
  fs.writeFileSync(file, code.replace(oldCode, newCode));
  console.log('patched');
} else {
  console.log('not found');
}
EOF
node patch_test.js
